// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.smsimport com.roshan.persona.connectivity.model.SmsDirectionimport com.roshan.persona.connectivity.model.SmsMessageimport com.roshan.persona.connectivity.model.SmsStatus/** * NOUS — SMS Services (Module 11 v3 — Step 11.4). * * Service interfaces for SMS operations — wraps Android's SmsManager + * Telephony.Sms content provider for testability. */// ──────────────────────────────────────────────────────────────────────────// SMS Service (wraps SmsManager)// ──────────────────────────────────────────────────────────────────────────/** * Interface for sending SMS messages. * * Real implementation ([AndroidSmsService]) wraps SmsManager. * Tests inject a fake. */interface SmsService {    /**     * Send an SMS to [phoneNumber] with [message].     *     * @return the delivery status (SENT / FAILED / PERMISSION_DENIED).     */    suspend fun send(phoneNumber: String, message: String): SmsStatus    /** True if SEND_SMS permission is granted. */    fun hasPermission(): Boolean}// ──────────────────────────────────────────────────────────────────────────// SMS History Service (wraps Telephony.Sms)// ──────────────────────────────────────────────────────────────────────────/** * Interface for reading SMS history. * * Real implementation ([AndroidSmsHistoryService]) wraps Telephony.Sms. * Tests inject a fake. */interface SmsHistoryService {    /** Get all SMS since [sinceMs], most-recent-first. */    suspend fun getSmsHistory(sinceMs: Long): List<SmsMessage>    /** Get unread incoming SMS. */    suspend fun getUnreadSms(): List<SmsMessage>    /** Get SMS from/to [phoneNumber] since [sinceMs]. */    suspend fun getSmsForContact(phoneNumber: String, sinceMs: Long): List<SmsMessage>    /** Mark an SMS as read. */    suspend fun markAsRead(messageId: String): Boolean    /** Delete an SMS. */    suspend fun deleteSms(messageId: String): Boolean    /** Delete all SMS. */    suspend fun deleteAll(): Int}// ──────────────────────────────────────────────────────────────────────────// PII Scrubber (privacy protection)// ──────────────────────────────────────────────────────────────────────────/** * NOUS — PII Scrubber (Module 11 v3 — Step 11.4). * * Scrubs personally identifiable information from SMS content before * passing it to the local LLM for smart reply generation. * * ## What gets scrubbed * *  - Phone numbers → [PHONE] *  - Email addresses → [EMAIL] *  - OTPs (4-8 digit codes) → [OTP] *  - URLs → [URL] *  - Credit card numbers → [CARD] * * ## Privacy * * The scrubbed text is what the LLM sees — never the raw PII. * The LLM generates a reply based on context, not personal data. */object PiiScrubber {    private val PHONE_REGEX = Regex("\\+?\\d{10,13}")    private val EMAIL_REGEX = Regex("[\\w.+-]+@[\\w-]+\\.[\\w.-]+")    private val OTP_REGEX = Regex("\\b\\d{4,8}\\b")    private val URL_REGEX = Regex("https?://\\S+")    private val CARD_REGEX = Regex("\\b\\d{4}[\\s-]?\\d{4}[\\s-]?\\d{4}[\\s-]?\\d{4}\\b")    /**     * Scrub PII from [text].     *     * @return the scrubbed text with PII replaced by placeholders.     */    fun scrub(text: String): String {        var result = text        result = CARD_REGEX.replace(result, "[CARD]")        result = URL_REGEX.replace(result, "[URL]")        result = EMAIL_REGEX.replace(result, "[EMAIL]")        result = PHONE_REGEX.replace(result, "[PHONE]")        result = OTP_REGEX.replace(result, "[OTP]")        return result    }    /**     * Check if [text] contains any PII.     */    fun containsPii(text: String): Boolean {        return PHONE_REGEX.containsMatchIn(text) ||            EMAIL_REGEX.containsMatchIn(text) ||            OTP_REGEX.containsMatchIn(text) ||            URL_REGEX.containsMatchIn(text) ||            CARD_REGEX.containsMatchIn(text)    }    /**     * Extract OTP from text (if present).     *     * Useful for "NOUS, read the OTP" — extracts the 4-8 digit code.     *     * @return the OTP, or null if not found.     */    fun extractOtp(text: String): String? {        // Look for common OTP patterns: "OTP is 123456", "code: 1234", "verification: 123456"        val otpPattern = Regex("(?:otp|code|verification|password)[:\\s]+(\\d{4,8})", RegexOption.IGNORE_CASE)        otpPattern.find(text)?.let { return it.groupValues[1] }        // Fallback: just find a 4-8 digit number.        return OTP_REGEX.find(text)?.value    }}